// Banco de questoes - Geografia (Cap. 9 Centro-Oeste e Cap. 10 Nordeste) - 5o ano - prova 24/11
window.BANCO = window.BANCO || {};
window.BANCO.geografia = [
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Quais unidades da federação formam a Região Centro-Oeste?",a:["Mato Grosso, Mato Grosso do Sul, Goiás e Distrito Federal","Minas Gerais, Goiás, Bahia e Distrito Federal","Mato Grosso, Rondônia, Tocantins e Goiás","Mato Grosso do Sul, Paraná, São Paulo e Goiás"],c:0,e:"O Centro-Oeste tem três estados (Mato Grosso, Mato Grosso do Sul e Goiás) e o Distrito Federal, onde fica Brasília."},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Qual é a capital de Mato Grosso?",a:["Campo Grande","Cuiabá","Goiânia","Porto Velho"],c:1,e:"Cuiabá é a capital de Mato Grosso. Cuidado para não confundir: Campo Grande é a capital de Mato Grosso do Sul."},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Campo Grande é a capital de qual estado?",a:["Mato Grosso","Goiás","Mato Grosso do Sul","Tocantins"],c:2,e:"Campo Grande é a capital de Mato Grosso do Sul, o estado que fica ao sul de Mato Grosso. Já a capital de Mato Grosso é Cuiabá."},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Qual é a capital de Goiás?",a:["Anápolis","Brasília","Cuiabá","Goiânia"],c:3,e:"Goiânia é a capital de Goiás. Anápolis também fica em Goiás, mas não é a capital."},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Em qual unidade da federação fica Brasília, a capital do Brasil?",a:["No Distrito Federal","Em Goiás","Em Mato Grosso","Em Minas Gerais"],c:0,e:"Brasília fica no Distrito Federal, que não é um estado: é a unidade criada para abrigar a capital do país. 🏛️"},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"Uma característica da localização do Centro-Oeste é que ele:",a:["Fica no litoral do Oceano Atlântico","Não é banhado pelo mar","Faz fronteira com a Argentina e o Uruguai","Fica no extremo sul do Brasil"],c:1,e:"O Centro-Oeste fica no interior do Brasil: é a única região brasileira que não tem litoral."},
{n:"f",t:"Centro-Oeste: aspectos gerais",q:"O clima tropical, que predomina no Centro-Oeste, tem:",a:["Neve em todos os invernos","Chuva forte o ano inteiro, sem mês seco","Verão chuvoso e inverno seco","Frio intenso o ano todo"],c:2,e:"No clima tropical do Centro-Oeste há duas estações bem marcadas: o verão quente e chuvoso e o inverno seco. ☀️🌧️"},
{n:"f",t:"Cerrado",q:"Qual é a vegetação que predomina no Centro-Oeste?",a:["Caatinga","Cerrado","Mata de Araucárias","Pampa"],c:1,e:"O Cerrado é a vegetação que domina a maior parte do Centro-Oeste, com árvores baixas, arbustos e muito capim."},
{n:"f",t:"Cerrado",q:"Como são as árvores típicas do Cerrado?",a:["Altíssimas, com troncos finos, retos e lisos","Baixas, de troncos tortos e casca grossa","Cobertas de espinhos e sem nenhuma folha","Pinheiros em forma de guarda-chuva"],c:1,e:"As árvores do Cerrado costumam ser baixas, com galhos e troncos retorcidos e casca grossa, que ajuda a protegê-las do fogo."},
{n:"f",t:"Cerrado",q:"Por que muitas plantas do Cerrado têm raízes muito profundas?",a:["Para se esconder dos animais que comem folhas","Para buscar água no fundo do solo na seca","Para conseguir crescer em direção ao mar","Para se proteger da neve que cai no inverno"],c:1,e:"Na estação seca quase não chove, e a água fica guardada lá no fundo do solo. As raízes profundas funcionam como canudinhos que vão buscar essa água! 💧"},
{n:"f",t:"Cerrado",q:"Qual destes animais é típico do Cerrado?",a:["Lobo-guará","Pinguim","Urso-polar","Camelo"],c:0,e:"O lobo-guará, de pernas compridas e pelo alaranjado, é um dos símbolos do Cerrado. 🐺"},
{n:"f",t:"Cerrado",q:"O Cerrado é chamado de 'berço das águas' porque:",a:["É totalmente coberto pela água do oceano","Lá nascem muitos rios importantes do Brasil","Chove forte todos os dias do ano, sem parar","Tem o maior lago de água salgada do mundo"],c:1,e:"No Cerrado nascem rios que formam várias das grandes bacias hidrográficas do Brasil. Por isso ele é chamado de 'berço das águas'."},
{n:"f",t:"Cerrado",q:"O que costuma acontecer no Cerrado durante a estação seca?",a:["A vegetação fica coberta de neve e gelo","Toda a região fica alagada pelas cheias dos rios","O capim seca e as queimadas ficam mais comuns","As árvores crescem muito e formam uma floresta fechada"],c:2,e:"Na seca, o capim fica sequinho e pega fogo com facilidade. Por isso as queimadas aumentam nessa época do ano. 🔥"},
{n:"f",t:"Cerrado",q:"Qual é a principal causa do desmatamento do Cerrado?",a:["A construção de grandes estações de esqui","A pesca industrial em alto-mar","O avanço das geleiras sobre a vegetação","A abertura de áreas para lavouras e pastos"],c:3,e:"Grande parte do Cerrado foi derrubada para dar lugar a plantações (como a soja) e a pastos para o gado."},
{n:"f",t:"Pantanal",q:"O que é o Pantanal?",a:["Uma cadeia de montanhas altas e com neve no topo","Uma grande planície que alaga em parte do ano","Um deserto de areia onde quase nunca chove","Uma floresta fechada de pinheiros e araucárias"],c:1,e:"O Pantanal é uma enorme planície que fica alagada durante parte do ano, quando os rios transbordam. É considerado a maior planície alagável do mundo! 🌊"},
{n:"f",t:"Pantanal",q:"O Pantanal fica em quais estados do Centro-Oeste?",a:["Distrito Federal e Mato Grosso do Sul","Mato Grosso e Mato Grosso do Sul","Goiás e Tocantins","Goiás e Distrito Federal"],c:1,e:"O Pantanal brasileiro fica em Mato Grosso e em Mato Grosso do Sul. Ele também se estende um pouco pela Bolívia e pelo Paraguai."},
{n:"f",t:"Pantanal",q:"Qual ave é considerada o símbolo do Pantanal?",a:["Tuiuiú","Pinguim","Gaivota","Avestruz"],c:0,e:"O tuiuiú é uma ave grande, de pescoço preto e vermelho, que é o símbolo do Pantanal. 🐦"},
{n:"f",t:"Pantanal",q:"O que são as cheias no Pantanal?",a:["A época em que cai neve e os rios congelam","A época em que os rios transbordam e alagam a planície","A época em que não chove nada durante meses","A época em que o oceano invade a região pela costa"],c:1,e:"Na época das chuvas, os rios enchem, transbordam e cobrem grande parte da planície de água. Essa é a cheia do Pantanal."},
{n:"f",t:"Pantanal",q:"Qual destes animais vive no Pantanal?",a:["Canguru","Pinguim","Jacaré","Urso-panda"],c:2,e:"O jacaré é um dos animais mais comuns do Pantanal, que também abriga capivaras, onças-pintadas e ariranhas. 🐊"},
{n:"f",t:"Pantanal",q:"Qual atividade econômica tradicional é praticada no Pantanal há muito tempo?",a:["Extração de petróleo no mar","Pesca de baleias","Criação de gado (pecuária)","Plantação de trigo na neve"],c:2,e:"A criação de gado é feita no Pantanal há séculos, aproveitando os pastos naturais da planície. Os peões pantaneiros conduzem as boiadas. 🐄"},
{n:"f",t:"Pantanal",q:"O Pantanal recebeu da UNESCO o título de:",a:["Maior deserto de areia da América do Sul","Patrimônio Natural da Humanidade","Cidade mais populosa de todo o planeta","Maior geleira do continente americano"],c:1,e:"Por sua natureza tão rica e especial, o Pantanal foi reconhecido pela UNESCO como Patrimônio Natural da Humanidade."},
{n:"f",t:"Atividades econômicas",q:"Qual é a principal atividade econômica do Centro-Oeste?",a:["A pesca em alto-mar","A construção de navios","A extração de sal marinho","A agropecuária"],c:3,e:"A agropecuária (plantações e criação de animais) é a atividade mais importante do Centro-Oeste. 🚜"},
{n:"f",t:"Atividades econômicas",q:"Qual grão é o principal produto agrícola do Centro-Oeste?",a:["Trigo","Soja","Cacau","Uva"],c:1,e:"A soja é o grande destaque da agricultura do Centro-Oeste. A região é a maior produtora de soja do Brasil."},
{n:"f",t:"Atividades econômicas",q:"O que é agropecuária?",a:["A fabricação de carros, motos e caminhões","A agricultura e a criação de animais","O comércio de roupas nos shoppings","A pesca de peixes e camarões no mar"],c:1,e:"Agropecuária junta duas atividades: a agricultura (plantar) e a pecuária (criar animais, como bois e porcos)."},
{n:"f",t:"Atividades econômicas",q:"Qual animal é criado em grandes rebanhos no Centro-Oeste?",a:["Camelos","Renas","Gado bovino","Lhamas"],c:2,e:"O Centro-Oeste tem enormes rebanhos de gado bovino (bois e vacas), criados para produzir carne e leite. 🐂"},
{n:"f",t:"Atividades econômicas",q:"O uso de tratores e colheitadeiras nas grandes fazendas do Centro-Oeste é chamado de:",a:["Mecanização","Urbanização","Industrialização das cidades","Extrativismo"],c:0,e:"Mecanização é o uso de máquinas no campo. Com elas, as fazendas plantam e colhem áreas enormes muito mais rápido."},
{n:"f",t:"Atividades econômicas",q:"Qual destes lugares do Centro-Oeste é famoso pelo turismo em rios de águas cristalinas?",a:["Gramado (RS)","Ouro Preto (MG)","Campos do Jordão (SP)","Bonito (MS)"],c:3,e:"Bonito, em Mato Grosso do Sul, é famoso por seus rios de águas tão transparentes que dá para ver os peixes nadando! 🐟"},
{n:"f",t:"Atividades econômicas",q:"Por que tantas rodovias e ferrovias foram construídas no Centro-Oeste?",a:["Para transportar a produção até portos e cidades","Para levar turistas até as praias da região","Para trazer gelo das montanhas até as fazendas","Para impedir que os moradores viajem para fora"],c:0,e:"O Centro-Oeste produz muitos grãos e carne, mas fica longe do mar. Estradas e ferrovias levam essa produção até os portos e às cidades."},
{n:"f",t:"Povos indígenas",q:"Qual é o nome da grande área indígena criada em 1961 em Mato Grosso?",a:["Parque Nacional da Tijuca","Parque Indígena do Xingu","Parque do Ibirapuera","Parque Nacional de Aparados da Serra"],c:1,e:"O Parque Indígena do Xingu foi criado em 1961, em Mato Grosso, para proteger os povos indígenas que vivem ali."},
{n:"f",t:"Povos indígenas",q:"Quem foram os irmãos Villas-Bôas?",a:["Jogadores de futebol que fundaram um grande clube em Goiânia","Sertanistas que lutaram pela criação do Parque do Xingu","Arquitetos que desenharam os prédios de Brasília","Cantores que criaram o ritmo do forró"],c:1,e:"Orlando, Cláudio e Leonardo Villas-Bôas eram sertanistas: exploraram o interior do Brasil e defenderam os indígenas, ajudando a criar o Parque do Xingu."},
{n:"f",t:"Povos indígenas",q:"O que é a demarcação de terras indígenas?",a:["A venda das terras indígenas para grandes fazendeiros","Marcar oficialmente os limites das terras indígenas","A mudança dos povos indígenas para as grandes cidades","A construção de rodovias que atravessam as aldeias"],c:1,e:"Demarcar é marcar oficialmente os limites da terra de um povo indígena, garantindo que ela pertença a ele e seja protegida."},
{n:"f",t:"Povos indígenas",q:"No Centro-Oeste vivem muitos povos indígenas diferentes. Isso mostra que:",a:["Há grande diversidade de povos, línguas e costumes","Todos os povos indígenas têm exatamente os mesmos costumes","Os povos indígenas deixaram de existir na região","Todos os indígenas falam uma única língua, o tupi"],c:0,e:"Cada povo indígena tem sua própria língua, suas festas e seu jeito de viver. Essa variedade se chama diversidade cultural."},
{n:"f",t:"Povos indígenas",q:"Qual destes é um povo indígena que vive no Centro-Oeste brasileiro?",a:["Vikings","Xavante","Maias","Samurais"],c:1,e:"Os Xavante vivem em Mato Grosso. Outros povos do Centro-Oeste são os Bororo, os Terena e os Guarani-Kaiowá."},
{n:"f",t:"Conflitos pela terra",q:"O que é um latifúndio?",a:["Uma pequena horta no quintal de casa","Uma propriedade rural muito grande","Um prédio de apartamentos na cidade","Um rio que seca durante a estiagem"],c:1,e:"Latifúndio é uma propriedade rural enorme, que pertence a uma só pessoa ou empresa."},
{n:"f",t:"Conflitos pela terra",q:"Os conflitos pela terra no Centro-Oeste acontecem principalmente entre:",a:["Fazendeiros, indígenas e pequenos agricultores","Torcedores de times de futebol das capitais da região","Pescadores e marinheiros do litoral","Comerciantes e turistas dos shoppings"],c:0,e:"Fazendeiros, povos indígenas, posseiros e pequenos agricultores muitas vezes disputam as mesmas terras, o que gera conflitos."},
{n:"f",t:"Conflitos pela terra",q:"O que é a grilagem de terras?",a:["A criação de grilos para vender como alimento","A ocupação de terras com documentos falsos","A plantação de soja em áreas de cerrado","A festa tradicional da colheita do milho"],c:1,e:"Grilagem é tomar terras usando documentos falsos. O nome vem de um truque antigo: deixar papéis numa gaveta com grilos para que parecessem velhos! 🦗"},
{n:"f",t:"Povoamento e urbanização",q:"Em que ano Brasília foi inaugurada e se tornou a capital do Brasil?",a:["1500","1822","1960","2000"],c:2,e:"Brasília foi inaugurada em 21 de abril de 1960 e passou a ser a capital do Brasil no lugar do Rio de Janeiro."},
{n:"f",t:"Povoamento e urbanização",q:"Qual presidente mandou construir Brasília?",a:["Dom Pedro I","Marechal Deodoro da Fonseca","Juscelino Kubitschek","Getúlio Vargas"],c:2,e:"Juscelino Kubitschek, o JK, foi o presidente que construiu Brasília e transferiu a capital para o interior do país."},
{n:"f",t:"Povoamento e urbanização",q:"Qual cidade era a capital do Brasil antes de Brasília?",a:["Salvador","Rio de Janeiro","São Paulo","Belo Horizonte"],c:1,e:"Antes de 1960, a capital do Brasil era o Rio de Janeiro. E antes dele, lá no período colonial, foi Salvador."},
{n:"f",t:"Povoamento e urbanização",q:"Como eram chamados os trabalhadores que vieram de várias partes do país para construir Brasília?",a:["Bandeirantes","Tropeiros","Jangadeiros","Candangos"],c:3,e:"Os candangos foram os trabalhadores que construíram Brasília. Muitos vieram do Nordeste, de Minas Gerais e de Goiás. 👷"},
{n:"f",t:"Povoamento e urbanização",q:"Qual arquiteto projetou prédios famosos de Brasília, como o Congresso Nacional e a Catedral?",a:["Santos Dumont","Oscar Niemeyer","Monteiro Lobato","Machado de Assis"],c:1,e:"Oscar Niemeyer projetou os principais prédios de Brasília, com curvas e formas muito criativas."},
{n:"f",t:"Povoamento e urbanização",q:"Por que as cidades do Centro-Oeste cresceram muito nas últimas décadas?",a:["Chegada de migrantes em busca de trabalho e terras","Descoberta de novas praias e portos no litoral da região","Fim de todas as fazendas e plantações da região","Mudança da capital do Brasil para Cuiabá"],c:0,e:"Muitas pessoas de outras regiões foram para o Centro-Oeste buscar trabalho e terras. Assim as cidades cresceram bastante."},
{n:"f",t:"Povoamento e urbanização",q:"Hoje, a maior parte da população do Centro-Oeste vive:",a:["No campo, em sítios e fazendas","Nas cidades","Em aldeias dentro do Pantanal","Em barcos nos rios da região"],c:1,e:"Mesmo sendo uma região de muitas fazendas, a maior parte das pessoas do Centro-Oeste mora nas cidades (área urbana). 🏙️"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Quantos estados formam a Região Nordeste?",a:["Cinco","Sete","Nove","Quatro"],c:2,e:"O Nordeste tem nove estados: Maranhão, Piauí, Ceará, Rio Grande do Norte, Paraíba, Pernambuco, Alagoas, Sergipe e Bahia. É a região com mais estados!"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual é a capital da Bahia?",a:["Salvador","Recife","Fortaleza","Aracaju"],c:0,e:"Salvador é a capital da Bahia. Ela também foi a primeira capital do Brasil!"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Fortaleza é a capital de qual estado?",a:["Pernambuco","Ceará","Rio Grande do Norte","Piauí"],c:1,e:"Fortaleza é a capital do Ceará, famosa por suas praias e jangadas. ⛵"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual é a capital de Pernambuco?",a:["Maceió","Natal","João Pessoa","Recife"],c:3,e:"Recife é a capital de Pernambuco. Ela é cortada por rios e pontes e é conhecida pelo frevo."},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"São Luís é a capital de qual estado nordestino?",a:["Piauí","Paraíba","Maranhão","Sergipe"],c:2,e:"São Luís é a capital do Maranhão e fica em uma ilha."},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual destes estados faz parte do Nordeste?",a:["Goiás","Paraíba","Espírito Santo","Pará"],c:1,e:"A Paraíba é um estado do Nordeste, e sua capital é João Pessoa. Goiás é do Centro-Oeste, o Espírito Santo é do Sudeste e o Pará é do Norte."},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual rio que atravessa vários estados do Nordeste é carinhosamente chamado de 'Velho Chico'?",a:["Rio Tietê","Rio Paraná","Rio Amazonas","Rio São Francisco"],c:3,e:"O rio São Francisco é o 'Velho Chico'. Ele leva água para o interior seco do Nordeste e é muito importante para a região."},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Os Lençóis Maranhenses são famosos por:",a:["Montanhas altas cobertas de neve no inverno","Dunas de areia branca com lagoas de chuva","Florestas de pinheiros e araucárias","Cavernas de gelo e geleiras antigas"],c:1,e:"Nos Lençóis Maranhenses há enormes dunas de areia branca e, na época das chuvas, lagoas azuis e verdes se formam entre elas. 🏜️💧"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual é a vegetação típica do interior seco do Nordeste?",a:["Caatinga","Pampa","Mata de Araucárias","Floresta Amazônica"],c:0,e:"A Caatinga é a vegetação do interior seco do Nordeste, com cactos e árvores que perdem as folhas na seca."},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"O Nordeste tem o litoral mais extenso do Brasil. Por isso, uma atividade muito importante na região é:",a:["O esqui nas montanhas","A criação de renas","O turismo nas praias","A extração de gelo"],c:2,e:"Com tantas praias bonitas, o turismo é muito importante no Nordeste e atrai visitantes do Brasil e do mundo. 🏖️"},
{n:"f",t:"Nordeste: paisagens e aspectos gerais",q:"Qual destes ritmos musicais é típico do Nordeste?",a:["Tango","Forró","Valsa","Polca"],c:1,e:"O forró é um ritmo nordestino tocado com sanfona, zabumba e triângulo, principalmente nas festas juninas. 🪗"},
{n:"f",t:"Sub-regiões do Nordeste",q:"Em quantas sub-regiões o Nordeste costuma ser dividido?",a:["Duas","Três","Quatro","Seis"],c:2,e:"O Nordeste é dividido em quatro sub-regiões: Zona da Mata, Agreste, Sertão e Meio-Norte."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Quais são as sub-regiões do Nordeste?",a:["Zona da Mata, Agreste, Sertão e Meio-Norte","Pantanal, Cerrado, Planalto Central e Vale do Xingu","Litoral, Serra, Pampa e Campanha","Zona Norte, Zona Sul, Centro e Oeste"],c:0,e:"As quatro sub-regiões do Nordeste são Zona da Mata, Agreste, Sertão e Meio-Norte. Cada uma tem clima e paisagem diferentes."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual sub-região do Nordeste fica no litoral leste e tem clima úmido?",a:["Sertão","Zona da Mata","Meio-Norte","Agreste"],c:1,e:"A Zona da Mata fica no litoral leste do Nordeste, onde chove bastante e o clima é úmido."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual é a maior sub-região do Nordeste?",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:2,e:"O Sertão é a maior sub-região do Nordeste e ocupa grande parte do interior, com clima semiárido."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual produto é cultivado na Zona da Mata desde o tempo da colonização?",a:["Cana-de-açúcar","Soja","Trigo","Maçã"],c:0,e:"Desde a época colonial, a Zona da Mata planta cana-de-açúcar, usada para fazer açúcar e, hoje, também álcool. 🍬"},
{n:"f",t:"Sub-regiões do Nordeste",q:"Como é o clima do Sertão nordestino?",a:["Muito chuvoso durante o ano inteiro","Frio, com neve nos meses de inverno","Semiárido, quente e com pouca chuva","Temperado, com quatro estações bem definidas"],c:2,e:"O Sertão tem clima semiárido: é quente, chove pouco e as chuvas são irregulares. ☀️"},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual sub-região fica entre a Zona da Mata e o Sertão?",a:["Meio-Norte","Agreste","Pantanal","Planalto Central"],c:1,e:"O Agreste é uma faixa de transição entre a úmida Zona da Mata e o seco Sertão."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual destas plantas é típica da Caatinga?",a:["Araucária","Vitória-régia","Pinheiro","Mandacaru"],c:3,e:"O mandacaru é um cacto típico da Caatinga. Ele guarda água dentro do caule para aguentar a seca. 🌵"},
{n:"f",t:"Sub-regiões do Nordeste",q:"O que é a seca no Sertão?",a:["Um longo período sem chuva","Uma grande enchente dos rios","Uma tempestade de neve forte","Um terremoto que racha o chão"],c:0,e:"A seca é um período longo em que quase não chove. Rios e açudes secam, e fica difícil plantar e criar animais."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual sub-região do Nordeste é formada pelo Maranhão e pelo oeste do Piauí?",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:3,e:"O Meio-Norte abrange o Maranhão e o oeste do Piauí. É uma área de transição entre a Amazônia e o Sertão."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Qual palmeira é típica da Mata dos Cocais?",a:["Ipê-amarelo","Babaçu","Mandacaru","Araucária"],c:1,e:"O babaçu é uma palmeira da Mata dos Cocais, no Meio-Norte. De seus cocos se tira óleo para fazer sabão e alimentos. 🌴"},
{n:"f",t:"Sub-regiões do Nordeste",q:"Caruaru (PE) e Campina Grande (PB), cidades famosas por suas grandes feiras e festas juninas, ficam em qual sub-região?",a:["Meio-Norte","Zona da Mata","Pantanal","Agreste"],c:3,e:"Caruaru e Campina Grande ficam no Agreste, sub-região conhecida por suas feiras e pelas grandes festas de São João. 🎉"},
{n:"f",t:"Sub-regiões do Nordeste",q:"Os rios do Sertão que secam durante a estiagem são chamados de:",a:["Perenes","Temporários","Navegáveis","Congelados"],c:1,e:"Rios temporários (ou intermitentes) secam na época sem chuva e voltam a correr quando chove."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Na Zona da Mata ficam algumas das maiores cidades do Nordeste, como:",a:["Cuiabá e Goiânia","Manaus e Belém","Salvador e Recife","Curitiba e Florianópolis"],c:2,e:"Salvador e Recife são grandes capitais da Zona da Mata, a sub-região mais povoada do Nordeste."},
{n:"f",t:"Sub-regiões do Nordeste",q:"Para guardar água para os períodos de seca, no Sertão são construídos:",a:["Pistas de patinação","Açudes e cisternas","Portos marítimos","Estufas de flores"],c:1,e:"Açudes são grandes reservatórios de água, e cisternas guardam a água da chuva que cai nos telhados. Assim a água dura até a próxima chuva. 💧"},
{n:"f",t:"Sub-regiões do Nordeste",q:"A sub-região do Meio-Norte é uma faixa de transição entre:",a:["A Amazônia e o Sertão","O Pantanal e o Pampa gaúcho","A Zona da Mata e o Agreste","O Cerrado e a Mata de Araucárias"],c:0,e:"O Meio-Norte fica entre a úmida Floresta Amazônica, a oeste, e o seco Sertão, a leste. Por isso tem características dos dois."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"Em área (tamanho do território), o Centro-Oeste é a ____ maior região do Brasil.",a:["Primeira","Segunda","Quarta","Quinta"],c:1,e:"O Centro-Oeste é a segunda maior região do Brasil em área: só perde para a Região Norte."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"A maior parte do relevo do Centro-Oeste é formada por:",a:["Planaltos, como o Planalto Central","Altas montanhas cobertas de neve eterna","Planícies litorâneas cheias de praias","Ilhas e arquipélagos no oceano"],c:0,e:"Grande parte do Centro-Oeste fica em planaltos, como o Planalto Central, onde está Brasília. A grande exceção é a planície do Pantanal."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"O Centro-Oeste faz fronteira com quais países?",a:["Argentina e Uruguai","Venezuela e Guiana","Bolívia e Paraguai","Peru e Colômbia"],c:2,e:"Mato Grosso faz fronteira com a Bolívia, e Mato Grosso do Sul faz fronteira com a Bolívia e o Paraguai."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"O que torna o Distrito Federal diferente das outras unidades da federação do Centro-Oeste?",a:["É a sede da capital do país, Brasília","É o único banhado pelo Oceano Atlântico","Pertence à Região Sudeste do Brasil","É o maior estado em área do Brasil"],c:0,e:"O Distrito Federal não é um estado: ele foi criado para abrigar Brasília, a capital do Brasil, onde funciona o governo federal."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"Qual destes rios nasce no Centro-Oeste, em Mato Grosso?",a:["Rio Paraguai","Rio Tietê","Rio São Francisco","Rio Negro"],c:0,e:"O rio Paraguai nasce em Mato Grosso e é o principal rio do Pantanal. O São Francisco nasce em Minas Gerais e o Tietê, em São Paulo."},
{n:"m",t:"Centro-Oeste: aspectos gerais",q:"O estado de Mato Grosso do Sul foi criado a partir da divisão de qual estado?",a:["Goiás","Mato Grosso","São Paulo","Paraná"],c:1,e:"Em 1977, a parte sul de Mato Grosso foi separada e virou o estado de Mato Grosso do Sul, com capital em Campo Grande."},
{n:"m",t:"Cerrado",q:"Para que serve a casca grossa de muitas árvores do Cerrado?",a:["Guardar a neve do inverno","Fazer a árvore boiar nas cheias","Proteger a planta do fogo","Atrair peixes para as raízes"],c:2,e:"A casca grossa funciona como uma capa protetora: ajuda a árvore a resistir às queimadas, comuns na estação seca. 🔥🌳"},
{n:"m",t:"Cerrado",q:"Qual é o segundo maior bioma do Brasil, que ocupa grande parte do Centro-Oeste?",a:["Amazônia","Cerrado","Caatinga","Pampa"],c:1,e:"O Cerrado é o segundo maior bioma do Brasil, atrás apenas da Amazônia, e cobre grande parte do Centro-Oeste."},
{n:"m",t:"Cerrado",q:"O Cerrado é considerado uma das savanas com maior biodiversidade do mundo. Isso quer dizer que ele tem:",a:["Grande variedade de plantas e animais","Poucas espécies, todas vindas de outros países","Apenas capim, sem árvores nem bichos","Só animais criados em fazendas"],c:0,e:"Biodiversidade é a variedade de seres vivos. O Cerrado tem milhares de espécies de plantas e muitos animais, como o lobo-guará e a ema."},
{n:"m",t:"Cerrado",q:"Qual destes é um fruto típico do Cerrado, muito usado na culinária de Goiás?",a:["Maçã","Kiwi","Pequi","Pera"],c:2,e:"O pequi é um fruto amarelinho do Cerrado, usado no famoso arroz com pequi. Mas cuidado: ele tem espinhos por dentro! 😄"},
{n:"m",t:"Cerrado",q:"Para usar o solo ácido do Cerrado na agricultura em grande escala, os produtores precisam:",a:["Cobrir com areia trazida da praia","Corrigir com calcário e adubos","Inundar com água salgada do mar","Queimar toda a vegetação todo ano"],c:1,e:"O solo do Cerrado é ácido e pobre em nutrientes. Com calcário e adubos, ele foi corrigido e passou a produzir muita soja e milho."},
{n:"m",t:"Cerrado",q:"Por que a destruição do Cerrado pode prejudicar os rios brasileiros?",a:["Porque lá nascem rios de grandes bacias do país","Porque o Cerrado fica no fundo do oceano","Porque os rios do Brasil nascem todos na neve","Porque o Cerrado não tem nenhuma relação com a água"],c:0,e:"Sem a vegetação, a água da chuva penetra menos no solo e as nascentes podem secar. Como muitos rios nascem no Cerrado, todo o país sente o efeito."},
{n:"m",t:"Cerrado",q:"Qual animal ameaçado de extinção, de focinho comprido e cauda peluda, vive no Cerrado e come formigas e cupins?",a:["Pinguim-imperador","Tamanduá-bandeira","Leão-marinho","Canguru"],c:1,e:"O tamanduá-bandeira usa sua língua comprida para comer formigas e cupins. Ele está ameaçado por causa do desmatamento e das queimadas. 🐜"},
{n:"m",t:"Pantanal",q:"Durante as cheias do Pantanal, o que os pecuaristas costumam fazer com o gado?",a:["Levam os bois para terrenos mais altos","Deixam os bois nadando durante meses","Vendem todo o rebanho para outros países","Colocam os bois dentro de barcos"],c:0,e:"Quando a água sobe, os peões levam o gado para as partes mais altas, que não alagam. Na vazante, os animais voltam aos pastos baixos."},
{n:"m",t:"Pantanal",q:"O que acontece no Pantanal na época da vazante (seca)?",a:["A água congela e forma lagos de gelo","O mar invade a planície pela costa","Começa a época das maiores enchentes do ano","As águas baixam e surgem pastos e lagoas"],c:3,e:"Na vazante, a água vai baixando: aparecem campos de pasto e lagoas cheias de peixes, que atraem muitas aves."},
{n:"m",t:"Pantanal",q:"Qual é o principal rio do Pantanal?",a:["Rio Tietê","Rio Paraguai","Rio São Francisco","Rio Amazonas"],c:1,e:"O rio Paraguai e seus afluentes são os responsáveis pelas cheias que alagam a planície do Pantanal."},
{n:"m",t:"Pantanal",q:"Qual grande felino, o maior das Américas, é encontrado no Pantanal?",a:["Leão","Tigre","Onça-pintada","Leopardo-das-neves"],c:2,e:"A onça-pintada é o maior felino das Américas, e o Pantanal é um dos melhores lugares do mundo para observá-la. 🐆"},
{n:"m",t:"Pantanal",q:"Além do Brasil, o Pantanal também se estende por quais países vizinhos?",a:["Chile e Argentina","Uruguai e Argentina","Peru e Equador","Bolívia e Paraguai"],c:3,e:"A maior parte do Pantanal fica no Brasil, mas uma parte dele está na Bolívia e no Paraguai."},
{n:"m",t:"Pantanal",q:"Qual destas atividades atrai muitos turistas para o Pantanal?",a:["Passeios para ver neve e geleiras nas montanhas","Surfe nas ondas do mar aberto","Observação de animais e pesca esportiva","Visitas a vulcões em atividade"],c:2,e:"Os turistas vão ao Pantanal para ver aves, jacarés, capivaras e onças, e para praticar a pesca esportiva. Isso é o ecoturismo. 📸"},
{n:"m",t:"Atividades econômicas",q:"Qual estado do Centro-Oeste é o maior produtor de soja do Brasil?",a:["Goiás","Mato Grosso","Mato Grosso do Sul","Distrito Federal"],c:1,e:"Mato Grosso é o maior produtor de soja do Brasil e também se destaca no milho, no algodão e na criação de gado."},
{n:"m",t:"Atividades econômicas",q:"O que é agroindústria?",a:["Fábrica que monta carros e motos perto das plantações","Loja que vende sementes na cidade","Plantação feita somente com máquinas","Indústria que transforma produtos do campo"],c:3,e:"A agroindústria transforma o que vem do campo: a soja vira óleo e ração, o boi vira carne embalada, a cana vira açúcar e álcool."},
{n:"m",t:"Atividades econômicas",q:"Qual destes produtos é feito pela agroindústria a partir da soja?",a:["Vidro","Óleo de cozinha","Aço","Cimento"],c:1,e:"O grão de soja é esmagado nas agroindústrias para produzir óleo de cozinha e farelo, usado em ração para animais."},
{n:"m",t:"Atividades econômicas",q:"A mecanização da agricultura no Centro-Oeste trouxe qual consequência para o trabalho no campo?",a:["São necessários menos trabalhadores nas lavouras","Mais pessoas passaram a colher tudo à mão, com enxadas e facões","As fazendas ficaram pequenas, como hortas","A produção de soja acabou na região"],c:0,e:"Uma colheitadeira faz o trabalho de muitas pessoas. Por isso, as fazendas mecanizadas empregam poucos trabalhadores."},
{n:"m",t:"Atividades econômicas",q:"Qual destes é um impacto ambiental da expansão das lavouras no Centro-Oeste?",a:["Formação de novas geleiras","Aumento da Mata Atlântica","Desmatamento do Cerrado","Fim de todas as queimadas"],c:2,e:"Para abrir novas lavouras e pastos, grandes áreas de Cerrado foram derrubadas, o que ameaça plantas, animais e nascentes."},
{n:"m",t:"Atividades econômicas",q:"Além da agropecuária, o Centro-Oeste tem mineração. Em Corumbá (MS), por exemplo, extraem-se:",a:["Petróleo no fundo do mar","Minério de ferro e manganês","Sal marinho","Carvão mineral do Sul"],c:1,e:"Na região de Corumbá, perto do Pantanal, há grandes jazidas de minério de ferro e de manganês. ⛏️"},
{n:"m",t:"Atividades econômicas",q:"Por que rodovias como a BR-163 e as ferrovias são importantes para o agronegócio do Centro-Oeste?",a:["Ajudam a levar os grãos até os portos","Servem apenas para passeios de turistas","Levam água do mar para irrigar as lavouras","Impedem que a soja seja vendida a outros países"],c:0,e:"As estradas e ferrovias levam a soja e o milho até os portos, de onde seguem de navio para outros países. Isso é o escoamento da produção. 🚛"},
{n:"m",t:"Povos indígenas",q:"O Parque Indígena do Xingu foi criado em 1961 com o objetivo de:",a:["Abrir espaço para grandes fazendas de soja","Construir uma nova capital para o Mato Grosso","Explorar as minas de ouro da região do rio","Proteger os povos indígenas e suas terras"],c:3,e:"O Parque do Xingu foi criado para proteger as terras, a natureza e a cultura de vários povos indígenas que vivem ali."},
{n:"m",t:"Povos indígenas",q:"Os irmãos Villas-Bôas participaram de qual expedição que explorou o interior do Brasil nos anos 1940?",a:["Esquadra de Pedro Álvares Cabral","Expedição Roncador-Xingu","Bandeira de Fernão Dias","Viagem de Santos Dumont"],c:1,e:"Na Expedição Roncador-Xingu, parte da Marcha para o Oeste, os irmãos Villas-Bôas conheceram os povos do Xingu e passaram a defendê-los."},
{n:"m",t:"Povos indígenas",q:"Qual ritual importante dos povos do Alto Xingu é feito em homenagem aos mortos?",a:["Quarup","Carnaval","Bumba meu boi","Festa do Divino"],c:0,e:"O Quarup é uma grande cerimônia dos povos do Alto Xingu para homenagear pessoas importantes que morreram, com cantos, danças e lutas."},
{n:"m",t:"Povos indígenas",q:"Qual destas é uma ameaça aos povos indígenas do Centro-Oeste?",a:["Aumento das áreas protegidas ao redor das aldeias","Demarcação de todas as terras que reivindicam","Invasão de terras por garimpeiros e madeireiros","Respeito às línguas e às tradições indígenas"],c:2,e:"Garimpeiros, madeireiros e outros invasores destroem a floresta, poluem os rios e ameaçam a vida e a cultura dos povos indígenas."},
{n:"m",t:"Povos indígenas",q:"Qual lei, de 1988, garante aos indígenas o direito às terras que tradicionalmente ocupam?",a:["Lei Áurea","Constituição Federal","Lei do Ventre Livre","Código de Trânsito"],c:1,e:"A Constituição Federal de 1988 reconhece o direito dos povos indígenas às terras onde tradicionalmente vivem."},
{n:"m",t:"Conflitos pela terra",q:"O que é um posseiro?",a:["Quem ocupa e cultiva uma terra sem ter o título dela","Dono de um enorme latifúndio, com todos os documentos registrados","Funcionário do governo que demarca as terras","Turista que visita as fazendas do Pantanal"],c:0,e:"O posseiro mora e trabalha numa terra, mas não tem o documento de propriedade. Por isso ele pode entrar em conflito com quem diz ser o dono."},
{n:"m",t:"Conflitos pela terra",q:"Por que a concentração de terras gera conflitos no campo?",a:["Todos os agricultores têm o mesmo tamanho de terra","Poucos têm muita terra e muitos não têm nenhuma","Não existe ninguém querendo trabalhar no campo","As terras são divididas igualmente pelo governo"],c:1,e:"Quando poucas pessoas são donas de quase toda a terra, muitas famílias ficam sem lugar para plantar e viver. Isso gera disputas."},
{n:"m",t:"Conflitos pela terra",q:"Por que muitos povos indígenas entram em conflito com fazendeiros em Mato Grosso do Sul?",a:["Porque os indígenas querem plantar soja nas cidades","Porque os fazendeiros querem morar nas aldeias","Porque todos querem pescar no mesmo rio do litoral","Porque disputam as mesmas terras"],c:3,e:"Muitas terras que os indígenas, como os Guarani-Kaiowá, ocupavam tradicionalmente viraram fazendas. Os dois lados disputam as mesmas áreas."},
{n:"m",t:"Conflitos pela terra",q:"Qual é o objetivo da reforma agrária?",a:["Dividir terras para quem quer trabalhar nelas","Juntar pequenos sítios em grandes latifúndios","Transformar todas as fazendas em cidades","Proibir a agricultura familiar no Brasil"],c:0,e:"A reforma agrária distribui terras pouco usadas para famílias que querem trabalhar nelas, diminuindo a concentração de terras."},
{n:"m",t:"Povoamento e urbanização",q:"Qual foi o nome da campanha do governo de Getúlio Vargas para incentivar a ocupação do interior do Brasil?",a:["Plano Real","Marcha para o Oeste","Diretas Já","Corrida do Ouro"],c:1,e:"A Marcha para o Oeste incentivou a ocupação do Centro-Oeste e da Amazônia, com expedições, estradas e novas cidades."},
{n:"m",t:"Povoamento e urbanização",q:"Qual capital do Centro-Oeste foi planejada e construída nos anos 1930 para substituir a antiga capital de Goiás?",a:["Cuiabá","Campo Grande","Goiânia","Brasília"],c:2,e:"Goiânia foi planejada nos anos 1930 para ser a nova capital de Goiás, no lugar da antiga Cidade de Goiás."},
{n:"m",t:"Povoamento e urbanização",q:"Qual foi o papel de Lúcio Costa na construção de Brasília?",a:["Criou o Plano Piloto, o desenho da cidade","Foi o presidente que mandou construir a cidade","Projetou o Congresso e a Catedral de Brasília","Foi o primeiro governador do Distrito Federal"],c:0,e:"Lúcio Costa foi o urbanista que desenhou o Plano Piloto. Os prédios, como o Congresso e a Catedral, foram projetados por Oscar Niemeyer."},
{n:"m",t:"Povoamento e urbanização",q:"O Plano Piloto de Brasília tem um formato que lembra:",a:["Um quadrado perfeito","Um avião","Uma estrela de cinco pontas","Um círculo"],c:1,e:"Visto de cima, o Plano Piloto lembra um avião (ou um pássaro de asas abertas). ✈️"},
{n:"m",t:"Povoamento e urbanização",q:"Por que o governo decidiu transferir a capital do Rio de Janeiro para o interior do país?",a:["Para ficar mais perto das praias do Nordeste","Porque o Rio de Janeiro foi abandonado","Para desenvolver e ocupar o interior do país","Para fugir do frio intenso do litoral"],c:2,e:"Levar a capital para o Planalto Central ajudou a ocupar e desenvolver o interior, que tinha poucos habitantes, e a integrar o país."},
{n:"m",t:"Povoamento e urbanização",q:"A partir dos anos 1970, muitos agricultores do Sul do Brasil migraram para Mato Grosso. O que eles buscavam?",a:["Praias e portos para pescar","Neve para praticar esportes de inverno","Empregos em estaleiros de navios","Terras mais baratas para plantar"],c:3,e:"Gaúchos, paranaenses e catarinenses foram para Mato Grosso porque lá as terras eram mais baratas. Eles fundaram cidades e plantaram soja."},
{n:"m",t:"Povoamento e urbanização",q:"O que acontece hoje com muitas cidades médias do Centro-Oeste, como Rio Verde (GO) e Sinop (MT)?",a:["Crescem com o agronegócio","Estão perdendo moradores por falta de chuva","Vivem só do turismo de praia","Foram abandonadas com o fim das fazendas"],c:0,e:"Essas cidades crescem por causa do agronegócio: têm agroindústrias, lojas de máquinas, serviços e recebem muitos moradores."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Qual é a única capital do Nordeste que não fica no litoral?",a:["Natal","Maceió","Teresina","Aracaju"],c:2,e:"Teresina, capital do Piauí, fica no interior, às margens do rio Parnaíba. Todas as outras capitais nordestinas ficam no litoral."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Qual cidade foi a primeira capital do Brasil e hoje é a capital da Bahia?",a:["Recife","Salvador","São Luís","Fortaleza"],c:1,e:"Salvador foi a primeira capital do Brasil, de 1549 a 1763. Depois a capital passou para o Rio de Janeiro."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Qual é o menor estado brasileiro em área, que fica no Nordeste?",a:["Bahia","Maranhão","Piauí","Sergipe"],c:3,e:"Sergipe é o menor estado do Brasil em área. Sua capital é Aracaju."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"João Pessoa é a capital de qual estado?",a:["Paraíba","Alagoas","Rio Grande do Norte","Sergipe"],c:0,e:"João Pessoa é a capital da Paraíba. Ela fica no ponto mais a leste das Américas! 🌅"},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Maceió e Aracaju são, respectivamente, as capitais de:",a:["Sergipe e Alagoas","Paraíba e Pernambuco","Alagoas e Sergipe","Piauí e Ceará"],c:2,e:"Maceió é a capital de Alagoas, e Aracaju é a capital de Sergipe. 'Respectivamente' quer dizer 'na mesma ordem'."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Natal é a capital de qual estado?",a:["Rio Grande do Sul","Ceará","Rio Grande do Norte","Pernambuco"],c:2,e:"Natal é a capital do Rio Grande do Norte, no Nordeste. Não confunda com o Rio Grande do Sul, que fica na Região Sul!"},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Por que o rio São Francisco é chamado de 'rio da integração nacional'?",a:["Porque liga o Sudeste ao Nordeste","Porque nasce e deságua no mesmo estado","Porque atravessa toda a Região Sul","Porque separa o Brasil da Argentina"],c:0,e:"O São Francisco nasce em Minas Gerais (Sudeste) e passa pela Bahia, Pernambuco, Alagoas e Sergipe, unindo regiões diferentes do país."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Em qual estado nasce o rio São Francisco?",a:["Na Bahia","Em Minas Gerais","Em Pernambuco","Em Goiás"],c:1,e:"O São Francisco nasce na Serra da Canastra, em Minas Gerais, e deságua no Oceano Atlântico, entre Alagoas e Sergipe."},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Qual bioma existe somente no Brasil e predomina no interior do Nordeste?",a:["Cerrado","Pampa","Caatinga","Mata Atlântica"],c:2,e:"A Caatinga é um bioma exclusivamente brasileiro: não existe em nenhum outro país do mundo! 🇧🇷"},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"O frevo e o maracatu são manifestações culturais típicas de qual estado nordestino?",a:["Rio Grande do Sul","Pernambuco","Santa Catarina","Amazonas"],c:1,e:"O frevo e o maracatu são tradições de Pernambuco, muito presentes no Carnaval de Recife e Olinda. 💃"},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"A literatura de cordel, muito popular no Nordeste, é:",a:["Livro de receitas de comidas típicas","Poesia popular em folhetos pendurados em cordões","Jornal diário publicado nas capitais","Dança feita com cordas nas festas de São João do sertão"],c:1,e:"O cordel é poesia popular impressa em folhetos, que eram vendidos pendurados em cordões nas feiras. Muitos têm capas de xilogravura. 📜"},
{n:"m",t:"Nordeste: paisagens e aspectos gerais",q:"Os ventos fortes e constantes do Nordeste são usados para produzir qual tipo de energia?",a:["Energia nuclear","Energia a carvão","Energia eólica","Energia geotérmica"],c:2,e:"A energia eólica vem do vento, que gira as hélices de grandes torres. O Nordeste é a região que mais produz esse tipo de energia no Brasil. 🌬️"},
{n:"m",t:"Sub-regiões do Nordeste",q:"Por que a Zona da Mata recebeu esse nome?",a:["Porque era coberta pela Mata Atlântica","Porque ainda tem a maior floresta do mundo","Porque fica no meio da Floresta Amazônica","Porque lá só existem cactos e espinhos"],c:0,e:"O nome vem da Mata Atlântica, a floresta que cobria todo o litoral leste quando os portugueses chegaram."},
{n:"m",t:"Sub-regiões do Nordeste",q:"O que aconteceu com a maior parte da Mata Atlântica da Zona da Mata?",a:["Foi derrubada para plantar cana e erguer cidades","Cresceu e passou a cobrir todo o Sertão nordestino","Foi preservada por completo e continua intacta","Virou uma grande área alagada como o Pantanal"],c:0,e:"Desde a colonização, a mata foi derrubada para retirar pau-brasil, plantar cana-de-açúcar e, depois, construir cidades. Restou bem pouco dela."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Como são, em geral, as propriedades rurais do Agreste?",a:["Pequenas e médias, com vários cultivos","Enormes, só com plantação de soja","Inexistentes, pois ninguém vive lá","Gigantes, com plantação de seringueiras"],c:0,e:"No Agreste predominam pequenas e médias propriedades que praticam a policultura: plantam feijão, milho, mandioca e frutas, e criam gado leiteiro."},
{n:"m",t:"Sub-regiões do Nordeste",q:"No Agreste, uma atividade importante que abastece as cidades vizinhas é:",a:["A pesca de baleias","A pecuária leiteira","A criação de renas","A extração de petróleo no mar"],c:1,e:"A criação de gado para produzir leite e queijo é muito importante no Agreste e abastece as cidades da Zona da Mata. 🧀"},
{n:"m",t:"Sub-regiões do Nordeste",q:"Qual é o principal problema causado pelo clima no Sertão?",a:["As nevascas","As secas longas","Os furacões","As geadas"],c:1,e:"Como chove pouco e de forma irregular, o Sertão sofre com secas longas, que prejudicam as plantações, os animais e as pessoas."},
{n:"m",t:"Sub-regiões do Nordeste",q:"O que significa a palavra 'caatinga', de origem tupi?",a:["Mata fechada","Rio grande","Mata branca","Terra molhada"],c:2,e:"Caatinga quer dizer 'mata branca'. Na seca, as árvores perdem as folhas e a vegetação fica com cor cinza-esbranquiçada."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Por que muitas árvores da Caatinga perdem as folhas na época da seca?",a:["Para perder menos água","Para receber mais neve","Porque são atacadas por peixes","Para crescer mais rápido"],c:0,e:"As plantas perdem água pelas folhas. Sem elas, gastam menos água e conseguem sobreviver até a chuva voltar. Quando chove, tudo fica verde de novo! 🌿"},
{n:"m",t:"Sub-regiões do Nordeste",q:"Na região de Petrolina (PE) e Juazeiro (BA), no Sertão, a produção de frutas como manga e uva é possível graças:",a:["À irrigação com água do rio São Francisco","Às chuvas fortes e constantes que caem o ano inteiro","Ao frio intenso do inverno sertanejo","À água do mar, que é doce na região"],c:0,e:"Com a água do rio São Francisco levada às plantações por irrigação, o Sertão produz frutas até para vender a outros países. 🥭🍇"},
{n:"m",t:"Sub-regiões do Nordeste",q:"Qual palmeira da Mata dos Cocais fornece uma cera usada em polidores, cosméticos e vernizes?",a:["Babaçu","Açaí","Carnaúba","Pupunha"],c:2,e:"Das folhas da carnaúba se tira uma cera muito útil. Ela é chamada de 'árvore da vida', porque quase tudo nela é aproveitado."},
{n:"m",t:"Sub-regiões do Nordeste",q:"O babaçu é importante no Meio-Norte porque:",a:["Do seu coco se tira óleo para sabão e alimentos","É um cacto do Sertão que guarda muita água no tronco grosso","Produz frutas usadas para fazer vinho","É a árvore que fornece a borracha"],c:0,e:"As quebradeiras de coco babaçu retiram as amêndoas do coco para fazer óleo, sabão e outros produtos. É uma importante fonte de renda."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Como as chuvas variam no Meio-Norte?",a:["Mais chuva a oeste, menos a leste","Mais chuva a leste, menos a oeste","Chove igual em toda a sub-região","Nunca chove em nenhum lugar"],c:0,e:"A oeste, perto da Amazônia (Maranhão), chove mais. A leste, perto do Sertão (Piauí), o clima vai ficando mais seco."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Por que o vaqueiro do Sertão usa roupas de couro, como o gibão e o chapéu?",a:["Para se proteger dos espinhos da Caatinga","Para se aquecer no frio intenso do Sertão","Para conseguir nadar nos rios da região","Para enfeitar-se para as festas de Carnaval"],c:0,e:"A Caatinga tem muitos galhos secos e espinhos. A roupa de couro protege o vaqueiro quando ele corre atrás do gado pelo mato. 🤠"},
{n:"m",t:"Sub-regiões do Nordeste",q:"Qual destas é uma característica da Zona da Mata?",a:["É a sub-região mais populosa do Nordeste","É a sub-região mais seca do Nordeste","Fica entre a Floresta Amazônica e o Sertão semiárido","É coberta pela Mata dos Cocais"],c:0,e:"A Zona da Mata foi ocupada primeiro pelos colonizadores e hoje concentra as maiores cidades e a maior parte da população do Nordeste."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Por que o Agreste é chamado de faixa de transição?",a:["Mistura traços da Zona da Mata e do Sertão","Fica entre o oceano Atlântico e a Zona da Mata, na praia","É igual à Floresta Amazônica","Muda de lugar todos os anos"],c:0,e:"O Agreste é menos úmido que a Zona da Mata e menos seco que o Sertão. Ele tem um pouco das características de cada um."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Os rios perenes são aqueles que:",a:["Secam durante a estiagem","Nunca secam, correm o ano inteiro","Só existem no inverno","Correm apenas debaixo da terra"],c:1,e:"Rio perene corre o ano todo, mesmo na seca. O São Francisco é o principal rio perene que atravessa o Sertão."},
{n:"m",t:"Sub-regiões do Nordeste",q:"Qual destas capitais nordestinas fica no Meio-Norte?",a:["São Luís","Recife","Salvador","Aracaju"],c:0,e:"São Luís, capital do Maranhão, fica no Meio-Norte. Recife, Salvador e Aracaju ficam na Zona da Mata."},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"Até 1988, o território do atual estado do Tocantins fazia parte de qual estado do Centro-Oeste?",a:["Goiás","Mato Grosso","Mato Grosso do Sul","Distrito Federal"],c:0,e:"Em 1988, o norte de Goiás foi separado e virou o estado do Tocantins, que hoje faz parte da Região Norte."},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"Um aluno descreveu uma região assim: 'não tem litoral, tem verão chuvoso e inverno seco, e lá nascem rios das bacias Amazônica e do Paraná-Paraguai'. Qual região ele descreveu?",a:["Sul","Centro-Oeste","Nordeste","Sudeste"],c:1,e:"Sem litoral, com clima tropical de verão chuvoso e inverno seco e com nascentes de grandes bacias: só pode ser o Centro-Oeste!"},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"Por que o Centro-Oeste é considerado um grande 'distribuidor de águas' do Brasil?",a:["Nos seus planaltos nascem rios de várias bacias","Recebe a água de todos os rios brasileiros antes de chegarem ao mar","Tem o maior trecho de litoral do Brasil","Tem chuvas iguais em todos os meses do ano"],c:0,e:"Dos planaltos do Centro-Oeste partem rios para o norte (bacias Amazônica e do Tocantins-Araguaia) e para o sul (bacia do Paraná e do Paraguai)."},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"Qual alternativa relaciona corretamente a unidade da federação e sua capital?",a:["Mato Grosso – Campo Grande","Mato Grosso do Sul – Cuiabá","Goiás – Goiânia","Distrito Federal – Goiânia"],c:2,e:"Goiás tem como capital Goiânia. As outras estão trocadas: Mato Grosso – Cuiabá; Mato Grosso do Sul – Campo Grande; Distrito Federal – Brasília."},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"O clima tropical do Centro-Oeste influencia a agricultura da região porque:",a:["O plantio costuma começar com a chegada das chuvas","Neva no inverno e impede qualquer plantio","Chove igual o ano todo, sem diferença entre as estações","Não existe estação seca, então nunca falta água"],c:0,e:"Como o inverno é seco, os agricultores esperam a chegada das chuvas, na primavera, para plantar a soja. A colheita acontece ainda na estação chuvosa. 🌱"},
{n:"d",t:"Centro-Oeste: aspectos gerais",q:"Comparando o Centro-Oeste com o Nordeste, é correto afirmar que:",a:["O Centro-Oeste é maior em área, mas tem menos habitantes","O Centro-Oeste tem mais estados que o Nordeste","O Nordeste não tem litoral, e o Centro-Oeste tem praias extensas","O Centro-Oeste é mais populoso que o Nordeste"],c:0,e:"O Centro-Oeste tem um território um pouco maior que o do Nordeste, mas muito menos gente. O Nordeste tem nove estados e é a segunda região mais populosa."},
{n:"d",t:"Cerrado",q:"Qual relação de causa e consequência sobre o Cerrado está correta?",a:["Expansão da soja e dos pastos → desmatamento do Cerrado","Aumento das chuvas → surgimento de geleiras no Cerrado","Desmatamento → aumento das nascentes de rios","Queimadas frequentes → solo mais protegido contra a erosão"],c:0,e:"Para plantar soja e criar gado, grandes áreas de Cerrado foram derrubadas. Desmatamento e queimadas deixam o solo desprotegido e podem secar nascentes."},
{n:"d",t:"Cerrado",q:"Algumas plantas do Cerrado conseguem brotar de novo logo depois de uma queimada. Isso acontece porque elas:",a:["Têm partes protegidas debaixo da terra","Têm folhas feitas de pedra","Nascem somente dentro dos rios","Não esquentam, pois o fogo do Cerrado nunca chega ao solo nem às plantas"],c:0,e:"Muitas plantas do Cerrado guardam raízes e caules grossos embaixo da terra, protegidos do fogo. Depois da queimada, elas brotam de novo."},
{n:"d",t:"Cerrado",q:"As veredas são áreas úmidas do Cerrado, perto de nascentes, marcadas por uma palmeira típica. Qual é ela?",a:["Carnaúba","Araucária","Babaçu","Buriti"],c:3,e:"O buriti é a palmeira das veredas do Cerrado. Carnaúba e babaçu são palmeiras da Mata dos Cocais, no Meio-Norte, e a araucária é do Sul."},
{n:"d",t:"Cerrado",q:"Compare o Cerrado e a Caatinga. Uma diferença correta entre eles é:",a:["O Cerrado tem um verão chuvoso; a Caatinga tem chuvas escassas","O Cerrado fica no litoral; a Caatinga fica na Amazônia","No Cerrado neva no inverno; na Caatinga chove o ano todo","O Cerrado não tem nenhuma árvore; a Caatinga é uma floresta fechada"],c:0,e:"O Cerrado tem uma estação chuvosa bem definida no verão. Já a Caatinga, no semiárido, recebe pouca chuva e de forma irregular."},
{n:"d",t:"Cerrado",q:"O Cerrado tem árvores afastadas umas das outras e muito capim entre elas. Esse tipo de vegetação é parecido com:",a:["As savanas da África","As florestas de pinheiros do Canadá","Os desertos de areia do Saara","As geleiras da Antártida"],c:0,e:"O Cerrado é um tipo de savana, como as savanas africanas: árvores espalhadas no meio de um tapete de capim. 🦒"},
{n:"d",t:"Cerrado",q:"Qual consequência o desmatamento do Cerrado traz para animais como o lobo-guará e o tamanduá-bandeira?",a:["Perda do habitat e risco de extinção","Aumento de alimento e de abrigo","Migração para as geleiras do sul","Mais espaço para viverem com segurança"],c:0,e:"Sem a vegetação nativa, esses animais perdem sua casa e seu alimento. Muitos também morrem atropelados nas estradas ou nas queimadas."},
{n:"d",t:"Cerrado",q:"Até meados do século XX, o Cerrado era pouco usado para a agricultura. O que mudou essa situação?",a:["Técnicas para corrigir o solo e sementes adaptadas","A descoberta de enormes poços de petróleo embaixo das lavouras","O fim da estação seca em toda a região","A chegada da neve, que fertilizou o solo"],c:0,e:"Pesquisas (como as da Embrapa) ensinaram a corrigir o solo ácido e criaram sementes de soja adaptadas ao clima do Cerrado. Assim a agricultura se expandiu."},
{n:"d",t:"Pantanal",q:"O desmatamento e a erosão nos planaltos ao redor do Pantanal causam qual problema na planície?",a:["Assoreamento dos rios, que ficam cheios de terra","Formação de geleiras nos rios","Aumento da profundidade dos rios, que ficam mais limpos","Fim das chuvas de verão"],c:0,e:"A terra solta dos planaltos é levada pela chuva até os rios do Pantanal e se acumula no fundo deles (assoreamento). Isso muda o caminho das águas, como aconteceu no rio Taquari."},
{n:"d",t:"Pantanal",q:"Por que as cheias são importantes para a vida no Pantanal?",a:["Espalham nutrientes e renovam pastos e lagoas","Destroem para sempre toda a vida que existe na planície","Trazem água salgada do oceano","Impedem a reprodução dos peixes"],c:0,e:"As águas das cheias espalham nutrientes pela planície, renovam os pastos e enchem as lagoas, onde os peixes se reproduzem. A natureza do Pantanal depende desse ritmo."},
{n:"d",t:"Pantanal",q:"Qual a diferença de relevo entre o Pantanal e a maior parte do Cerrado?",a:["Pantanal em planície; Cerrado sobretudo em planaltos","Pantanal em montanhas; Cerrado em planícies costeiras","Pantanal em planaltos; Cerrado em planícies alagáveis","Pantanal em serras altas; Cerrado no fundo de vales"],c:0,e:"O Pantanal é uma planície baixa, que alaga. O Cerrado ocupa principalmente os planaltos, como o Planalto Central."},
{n:"d",t:"Pantanal",q:"Uma pessoa viajou para uma planície de Mato Grosso e Mato Grosso do Sul onde os rios transbordam e alagam os campos na época das chuvas. Viu tuiuiús e jacarés e conheceu peões que conduzem o gado. Onde ela estava?",a:["Sertão","Zona da Mata","Pantanal","Lençóis Maranhenses"],c:2,e:"Planície alagável, tuiuiús, jacarés e peões com boiadas: todas são pistas do Pantanal!"},
{n:"d",t:"Pantanal",q:"Os grandes incêndios no Pantanal, como os de 2020, foram agravados principalmente por:",a:["Seca forte e uso do fogo para limpar pastos","Excesso de chuvas e enchentes durante todo o ano naquela região","Neve acumulada nas árvores","Aumento das cheias dos rios"],c:0,e:"Em 2020 houve uma seca muito forte. Com a vegetação seca, o fogo usado para limpar pastos saiu do controle e queimou uma grande parte do Pantanal."},
{n:"d",t:"Pantanal",q:"Por que a pecuária tradicional pantaneira é considerada adaptada ao ambiente do Pantanal?",a:["Usa pastos naturais e respeita o ritmo das cheias","Exige derrubar toda a vegetação nativa para plantar soja","Usa barcos para criar o gado dentro dos rios","Só funciona com o gado preso em estábulos"],c:0,e:"Na pecuária tradicional, o gado come o capim nativo da planície e é levado para áreas altas nas cheias, convivendo com o ciclo das águas."},
{n:"d",t:"Atividades econômicas",q:"Qual sequência explica o grande crescimento do agronegócio no Centro-Oeste?",a:["Terras planas + solo corrigido + máquinas → grandes safras","Muita neve + solo gelado + barcos → grandes safras","Litoral extenso + portos + pesca → grandes safras","Relevo montanhoso + chuvas o ano todo + enxadas → grandes safras"],c:0,e:"Os planaltos planos facilitam o uso de máquinas, o solo foi corrigido com calcário e a mecanização permitiu plantar áreas enormes. Resultado: grandes safras! 🌾"},
{n:"d",t:"Atividades econômicas",q:"A expansão da soja trouxe crescimento econômico ao Centro-Oeste, mas também problemas. Qual alternativa mostra um problema ambiental ligado a ela?",a:["Agrotóxicos que podem contaminar rios e solos","Aumento da área de floresta nativa preservada nas fazendas","Diminuição das queimadas em todo o Brasil","Melhora da qualidade da água das nascentes"],c:0,e:"O uso intenso de agrotóxicos nas grandes lavouras pode poluir o solo, os rios e prejudicar animais e pessoas."},
{n:"d",t:"Atividades econômicas",q:"Por que a agropecuária mecanizada do Centro-Oeste contribuiu para o êxodo rural?",a:["Máquinas substituíram trabalhadores no campo","O campo passou a precisar de mais trabalhadores","As cidades da região foram todas fechadas","As fazendas foram transformadas em praias"],c:0,e:"Com as máquinas, as fazendas precisam de poucos trabalhadores. Muitas pessoas do campo foram para as cidades em busca de emprego: isso é o êxodo rural."},
{n:"d",t:"Atividades econômicas",q:"Um município do Centro-Oeste tem frigoríficos, fábricas de ração e indústrias que produzem óleo de soja. Esse município se destaca pela:",a:["Indústria naval","Agroindústria","Pesca em alto-mar","Extração de petróleo"],c:1,e:"Frigoríficos, fábricas de ração e de óleo transformam produtos do campo: tudo isso é agroindústria, muito forte no Centro-Oeste."},
{n:"d",t:"Atividades econômicas",q:"Qual destes é um polo de ecoturismo do Centro-Oeste, com áreas de Cerrado, cachoeiras e cânions?",a:["Chapada Diamantina (BA)","Serra Gaúcha (RS)","Chapada dos Veadeiros (GO)","Lençóis Maranhenses (Maranhão)"],c:2,e:"A Chapada dos Veadeiros, em Goiás, tem cachoeiras e cânions no meio do Cerrado. A Chapada Diamantina também é linda, mas fica na Bahia, no Nordeste! 🏞️"},
{n:"d",t:"Atividades econômicas",q:"Por que o agronegócio do Centro-Oeste depende tanto de transporte eficiente?",a:["A produção é enorme e fica longe dos portos","A região fica à beira-mar, ao lado dos portos","Toda a produção é consumida na própria fazenda","Os grãos são levados de barco pelo mar da região"],c:0,e:"O Centro-Oeste produz muitos grãos, mas fica no interior, longe do mar. Sem boas estradas, ferrovias e hidrovias, o transporte fica caro e demorado."},
{n:"d",t:"Atividades econômicas",q:"Quando mal planejada, a criação de gado em grandes áreas do Centro-Oeste pode causar:",a:["Desmatamento para abrir pastos e erosão do solo","Aumento da vegetação nativa e das nascentes","Formação de dunas de areia branca e lagoas no litoral da região","Congelamento dos rios durante o inverno"],c:0,e:"Para formar pastos, a vegetação nativa é derrubada. Com o solo descoberto e pisoteado, a chuva arrasta a terra e causa erosão."},
{n:"d",t:"Povos indígenas",q:"Em imagens de satélite, o Parque Indígena do Xingu aparece como uma 'ilha verde' cercada de áreas desmatadas. O que isso mostra?",a:["Terras indígenas ajudam a conservar a vegetação","Os indígenas derrubam mais floresta do que os fazendeiros vizinhos","O parque fica no meio do oceano","Ao redor do parque a floresta está intacta"],c:0,e:"Dentro do parque a vegetação continua de pé, enquanto ao redor ela virou lavoura e pasto. As terras indígenas ajudam a proteger a natureza. 🛰️"},
{n:"d",t:"Povos indígenas",q:"As nascentes de vários rios que passam pelo Parque do Xingu ficam fora dele, em áreas de fazendas. Que problema isso pode causar aos povos indígenas?",a:["Rios poluídos por agrotóxicos e cheios de terra","Rios congelados durante o inverno","Rios com água salgada vinda do mar","Rios mais limpos, com mais peixes e com água mais transparente"],c:0,e:"O que acontece nas nascentes chega rio abaixo: agrotóxicos e terra das lavouras podem poluir a água e diminuir os peixes que os indígenas usam como alimento."},
{n:"d",t:"Povos indígenas",q:"Qual alternativa descreve corretamente o Parque Indígena do Xingu?",a:["Criado em 1961, em Mato Grosso, reúne vários povos","Criado em 1500, na Bahia, abriga um só povo","Criado em 1960, junto com Brasília, no Distrito Federal","Criado em 1888, em Goiás, para os bandeirantes"],c:0,e:"O Parque Indígena do Xingu foi criado em 1961, em Mato Grosso, e abriga mais de dez povos indígenas diferentes."},
{n:"d",t:"Povos indígenas",q:"Por que a demarcação das terras é tão importante para os povos indígenas?",a:["Garante a terra necessária para manter sua cultura","Obriga os indígenas a se mudarem para as cidades","Permite que grandes fazendeiros plantem soja dentro das aldeias","Proíbe os indígenas de caçar, pescar e plantar"],c:0,e:"Para os indígenas, a terra é onde caçam, pescam, plantam, fazem seus rituais e guardam sua história. Sem ela, sua cultura corre risco."},
{n:"d",t:"Povos indígenas",q:"Em Mato Grosso do Sul, os Guarani-Kaiowá lutam pela demarcação de suas terras. A principal causa desse conflito é que:",a:["Suas terras tradicionais foram ocupadas por fazendas","Eles desejam se mudar para as grandes capitais do Nordeste","Eles não querem mais viver em suas terras","As terras deles ficam no fundo do mar"],c:0,e:"Muitas áreas onde os Guarani-Kaiowá viviam viraram fazendas. Hoje eles vivem em espaços pequenos e lutam para recuperar suas terras tradicionais."},
{n:"d",t:"Conflitos pela terra",q:"Por que a grilagem aumenta os conflitos pela terra no Centro-Oeste?",a:["Terras são tomadas com papéis falsos, expulsando quem vive nelas","Os grilos destroem as plantações de soja","Ela distribui as terras de forma justa e com documentos verdadeiros a todas as famílias","Os fazendeiros devolvem as terras aos indígenas"],c:0,e:"O grileiro usa documentos falsos para se dizer dono de uma terra e tenta expulsar posseiros, indígenas e pequenos agricultores que já viviam ali."},
{n:"d",t:"Conflitos pela terra",q:"Qual situação mostra um conflito pela terra no Centro-Oeste?",a:["Fazendeiro cerca área reivindicada por indígenas","Família planta uma horta no quintal de casa","Turistas fazem passeios de barco pelo Pantanal para ver jacarés","Crianças brincam em uma praça de Goiânia"],c:0,e:"Quando um fazendeiro cerca uma área que os indígenas dizem ser sua terra tradicional, os dois lados disputam o mesmo lugar: é um conflito pela terra."},
{n:"d",t:"Conflitos pela terra",q:"A expansão das grandes fazendas sobre áreas de pequenos agricultores e povos tradicionais tende a:",a:["Aumentar a concentração de terras e os conflitos","Diminuir o tamanho dos latifúndios","Acabar com todos os conflitos no campo","Dividir a terra igualmente entre todos os moradores do campo"],c:0,e:"Quando as grandes fazendas crescem sobre as terras dos outros, a terra fica nas mãos de poucos e as disputas aumentam."},
{n:"d",t:"Povoamento e urbanização",q:"Qual é a ordem correta destes fatos da ocupação do Centro-Oeste?",a:["Brasília → Goiânia → ouro no séc. XVIII","Ouro no séc. XVIII → Goiânia → Brasília","Goiânia → Brasília → ouro no séc. XVIII","Brasília → ouro no séc. XVIII → Goiânia"],c:1,e:"Primeiro vieram os bandeirantes atrás de ouro (século XVIII), depois Goiânia foi construída (anos 1930) e por fim Brasília foi inaugurada (1960)."},
{n:"d",t:"Povoamento e urbanização",q:"Por que a construção de Brasília atraiu tantos migrantes, principalmente do Nordeste?",a:["Havia muito trabalho nas obras da nova capital","Brasília foi construída à beira-mar","No Nordeste não existia nenhuma cidade","O governo proibiu o trabalho em outras regiões"],c:0,e:"As obras de Brasília precisavam de milhares de trabalhadores. Muitos nordestinos, fugindo da seca e da pobreza, foram trabalhar lá e se tornaram candangos."},
{n:"d",t:"Povoamento e urbanização",q:"Muitos candangos que construíram Brasília não conseguiram morar no Plano Piloto. Onde muitos deles foram viver?",a:["Nas cidades-satélites, ao redor do Plano Piloto","Nos palácios e ministérios projetados por Oscar Niemeyer","Em ilhas no meio do lago Paranoá","No Rio de Janeiro, a antiga capital"],c:0,e:"Muitos trabalhadores foram morar em cidades-satélites, como Taguatinga e Ceilândia, que hoje são regiões administrativas do Distrito Federal."},
{n:"d",t:"Povoamento e urbanização",q:"Qual relação de causa e consequência sobre o povoamento do Centro-Oeste está correta?",a:["Novas rodovias → chegada de migrantes e cidades maiores","Construção de Brasília → diminuição da população","Expansão do agronegócio → fim de todas as cidades médias da região","Marcha para o Oeste → abandono do interior"],c:0,e:"As rodovias ligaram o Centro-Oeste ao resto do país. Com elas chegaram migrantes, e as cidades cresceram."},
{n:"d",t:"Povoamento e urbanização",q:"Goiânia e Brasília têm algo em comum. O quê?",a:["Foram planejadas para ser capitais","Foram fundadas pelos bandeirantes no século XVII","Ficam no litoral do Oceano Atlântico","Foram construídas durante a mineração do ouro"],c:0,e:"As duas são cidades planejadas: Goiânia foi desenhada nos anos 1930 para ser capital de Goiás, e Brasília, nos anos 1950, para ser a capital do Brasil."},
{n:"d",t:"Povoamento e urbanização",q:"O Centro-Oeste tem forte agropecuária, mas a maior parte de sua população vive nas cidades. Como isso se explica?",a:["O campo usa muitas máquinas, e os empregos ficam nas cidades","As fazendas mecanizadas empregam cada vez mais trabalhadores rurais","A população rural é maior que a urbana","As cidades da região não têm empregos"],c:0,e:"As fazendas mecanizadas precisam de pouca gente. Já as cidades concentram comércio, serviços e agroindústrias, que oferecem mais empregos."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Um turista visitou a única capital nordestina que fica longe do mar, às margens do rio Parnaíba. Qual é ela e em que estado fica?",a:["Teresina, no Piauí","São Luís, no Maranhão","Natal, no Rio Grande do Norte","Aracaju, em Sergipe"],c:0,e:"Teresina, capital do Piauí, fica no interior, entre os rios Parnaíba e Poti. É a única capital do Nordeste que não está no litoral."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Qual alternativa associa corretamente o estado nordestino e sua capital?",a:["Paraíba – Natal","Alagoas – Aracaju","Piauí – São Luís","Ceará – Fortaleza"],c:3,e:"Ceará – Fortaleza está certo. As outras estão trocadas: Paraíba – João Pessoa; Alagoas – Maceió; Piauí – Teresina."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Qual alternativa apresenta usos do rio São Francisco no Nordeste?",a:["Geração de energia nas hidrelétricas e irrigação","Transporte de geleiras e prática de esqui sobre o gelo do rio","Extração de petróleo do fundo do mar","Pesca de baleias e golfinhos"],c:0,e:"O São Francisco tem usinas hidrelétricas, como Sobradinho e Paulo Afonso, e sua água irriga plantações no Sertão. Também é usado para pesca e transporte."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"A transposição do rio São Francisco tem como objetivo:",a:["Levar água por canais a áreas do semiárido","Levar a água do rio para o oceano","Criar uma grande praia artificial no meio do Sertão","Secar o rio para plantar soja no leito"],c:0,e:"A transposição leva parte da água do São Francisco, por canais, para áreas secas do Ceará, da Paraíba, do Rio Grande do Norte e de Pernambuco."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Por que o litoral do Nordeste é muito mais povoado que o interior?",a:["A colonização começou pelo litoral, com cana e portos","O interior é coberto por geleiras e tem frio intenso o ano todo","No litoral não há chuvas","O interior é coberto pelo mar"],c:0,e:"Os portugueses ocuparam primeiro o litoral, onde plantaram cana e construíram portos e cidades. Além disso, o litoral leste tem clima úmido, e o interior é semiárido."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Qual alternativa mostra corretamente a diversidade de paisagens do Nordeste?",a:["Dunas no Maranhão, Caatinga no Sertão e Mata Atlântica no litoral","Pampa no Ceará, Pantanal na Bahia e Araucárias em Sergipe","Geleiras em Pernambuco, desertos em Alagoas e Pampa no Piauí","Floresta Amazônica cobrindo todo o litoral e neve nas serras do Sertão"],c:0,e:"O Nordeste tem paisagens muito diferentes: as dunas dos Lençóis Maranhenses, a Caatinga do Sertão, os restos de Mata Atlântica no litoral e a Mata dos Cocais."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Quantos estados do Nordeste têm litoral?",a:["Apenas cinco","Apenas três","Todos os nove","Só a Bahia"],c:2,e:"Todos os nove estados do Nordeste são banhados pelo Oceano Atlântico. O Piauí tem o menor litoral, mas também tem praias!"},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Qual estado nordestino tem o litoral mais extenso do Brasil?",a:["Piauí","Maranhão","Ceará","Bahia"],c:3,e:"A Bahia tem o maior litoral entre todos os estados brasileiros, com centenas de quilômetros de praias."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Qual afirmação sobre a Região Nordeste está correta?",a:["É a região com o maior número de estados do Brasil","É a região mais populosa e mais industrializada de todo o Brasil","Não tem nenhum estado com litoral","Fica totalmente no Hemisfério Norte"],c:0,e:"Com nove estados, o Nordeste é a região que tem mais estados. A região mais populosa e industrializada é o Sudeste."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Um viajante conheceu o forró e o São João de Campina Grande, o frevo no Recife e o bumba meu boi em São Luís. Isso mostra que:",a:["A cultura nordestina é rica e variada","Todos os estados têm a mesma festa","O Nordeste não tem tradições próprias","As festas vieram todas da Região Sul"],c:0,e:"Cada canto do Nordeste tem suas festas, músicas e danças. Essa variedade mostra como a cultura nordestina é rica. 🎶"},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"As lagoas que aparecem entre as dunas dos Lençóis Maranhenses se formam porque:",a:["A água da chuva se junta entre as dunas","O mar invade as dunas todos os dias","A neve das dunas derrete no verão","Vulcões antigos soltam água quente no meio da areia"],c:0,e:"Na época das chuvas, a água se acumula nas partes baixas entre as dunas e forma lagoas. Na seca, muitas delas diminuem ou secam."},
{n:"d",t:"Nordeste: paisagens e aspectos gerais",q:"Por que a produção de energia eólica cresceu tanto no Nordeste?",a:["Lá os ventos são fortes e sopram quase o ano todo","Lá neva muito e a neve gera eletricidade","Lá chove forte todos os dias e por isso os rios nunca secam","Lá não há sol e o céu está sempre nublado"],c:0,e:"Os ventos do Nordeste são fortes e constantes, no litoral e no interior. Isso é perfeito para girar as hélices das torres eólicas. 🌬️"},
{n:"d",t:"Sub-regiões do Nordeste",q:"Identifique a sub-região: 'faixa litorânea de clima úmido, onde a Mata Atlântica foi derrubada para o plantio de cana-de-açúcar e onde estão as maiores cidades da região'.",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:0,e:"Litoral úmido, Mata Atlântica, cana-de-açúcar e grandes cidades: essas são as marcas da Zona da Mata."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Identifique a sub-região: 'área de transição, com pequenas e médias propriedades, policultura, pecuária leiteira e grandes feiras, como as de Caruaru e Campina Grande'.",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:1,e:"Transição, pequenas propriedades, leite e feiras famosas: é o Agreste!"},
{n:"d",t:"Sub-regiões do Nordeste",q:"Identifique a sub-região: 'a maior de todas, com clima semiárido, chuvas escassas e irregulares, rios temporários e vegetação de Caatinga'.",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:2,e:"Semiárido, Caatinga e rios que secam: é o Sertão, a maior sub-região do Nordeste."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Identifique a sub-região: 'transição entre a Floresta Amazônica e o semiárido, com a Mata dos Cocais, de onde se extraem babaçu e carnaúba'.",a:["Zona da Mata","Agreste","Sertão","Meio-Norte"],c:3,e:"Mata dos Cocais, babaçu e carnaúba, entre a Amazônia e o Sertão: é o Meio-Norte."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Compare a Zona da Mata e o Sertão. Qual alternativa está correta?",a:["Zona da Mata: úmida e populosa; Sertão: semiárido e menos povoado","Zona da Mata: semiárida e vazia; Sertão: úmido e muito populoso","Zona da Mata: coberta de Caatinga; Sertão: coberto de Mata dos Cocais","Zona da Mata: fica no interior; Sertão: fica no litoral leste"],c:0,e:"A Zona da Mata, no litoral, é úmida e concentra a população. O Sertão, no interior, é semiárido e tem menos habitantes."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Por que o Agreste é um importante fornecedor de alimentos para as cidades da Zona da Mata?",a:["Suas pequenas propriedades produzem alimentos variados","Tem grandes plantações de cana para exportação","Produz apenas soja em enormes latifúndios mecanizados para exportar","Recebe todos os alimentos vindos do Sertão"],c:0,e:"Nas pequenas e médias propriedades do Agreste se plantam feijão, milho, mandioca e frutas e se produz leite. Tudo isso abastece as cidades do litoral."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Qual é a relação entre as chuvas irregulares do Sertão e a construção de açudes?",a:["Guardam a água das chuvas para usar na seca","Servem para levar a água do Sertão até o oceano, onde é guardada","São usados para fazer neve artificial","Impedem que chova no Sertão"],c:0,e:"Como as chuvas são poucas e irregulares, os açudes armazenam a água da época chuvosa para que ela possa ser usada nos meses secos."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Por que muitos rios do Sertão são temporários, enquanto o São Francisco é perene?",a:["O São Francisco nasce em área chuvosa, fora do semiárido","O São Francisco recebe água salgada do mar ao longo de todo o caminho","Os rios do Sertão nascem em geleiras que derretem","O São Francisco não passa pelo Sertão"],c:0,e:"O São Francisco nasce em Minas Gerais, onde chove bastante, e recebe água de afluentes de áreas úmidas. Por isso continua correndo mesmo atravessando o Sertão seco."},
{n:"d",t:"Sub-regiões do Nordeste",q:"A fruticultura irrigada de Petrolina (PE) e Juazeiro (BA) mostra que, no Sertão:",a:["Com irrigação, é possível produzir mesmo com pouca chuva","As chuvas são abundantes durante todo o ano","A Caatinga foi totalmente substituída pela Mata Atlântica nativa","Não é possível plantar nada sem neve"],c:0,e:"Com a água do rio São Francisco e tecnologia, o Sertão produz manga, uva e outras frutas, mesmo chovendo pouco. 🥭"},
{n:"d",t:"Sub-regiões do Nordeste",q:"Quais condições naturais favoreceram o cultivo da cana-de-açúcar na Zona da Mata desde a colonização?",a:["Clima quente e úmido e solo fértil","Clima frio e solo congelado","Clima semiárido, solo pedregoso e rios temporários","Neve no inverno e verão seco"],c:0,e:"A cana precisa de calor, chuva e solo fértil. A Zona da Mata tem clima quente e úmido e um solo escuro e fértil chamado massapê."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Na Mata dos Cocais, as quebradeiras de coco retiram do babaçu amêndoas usadas principalmente para fazer:",a:["Cera para polimento","Óleo e sabão","Borracha para pneus","Açúcar e álcool"],c:1,e:"Das amêndoas do babaçu se faz óleo e sabão. A cera para polimento vem da carnaúba, outra palmeira da Mata dos Cocais."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Por que o Meio-Norte é mais chuvoso a oeste do que a leste?",a:["O oeste fica mais perto da úmida Amazônia","O leste fica perto de montanhas com neve que bloqueiam as chuvas","O oeste recebe neve todo inverno","O leste é coberto pelo oceano"],c:0,e:"O oeste do Meio-Norte (Maranhão) está perto da Amazônia, que é muito úmida. Já o leste (Piauí) fica perto do Sertão semiárido."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Por que, no passado, muitos sertanejos migraram para outras regiões do Brasil?",a:["Fugiam das secas e buscavam trabalho em outras regiões","Queriam escapar da neve do inverno sertanejo","O Sertão tinha empregos demais nas fábricas e faltavam trabalhadores","Precisavam morar perto das geleiras"],c:0,e:"As secas prolongadas destruíam plantações e matavam o gado. Muitos sertanejos (os retirantes) foram para o Sudeste e o Centro-Oeste buscar trabalho."},
{n:"d",t:"Sub-regiões do Nordeste",q:"A pecuária no Sertão é geralmente extensiva. Isso significa que:",a:["O gado é criado solto, em grandes áreas","O gado é criado preso em estábulos com ração","O gado é criado dentro de barcos nos rios","O gado é criado em prédios nas cidades"],c:0,e:"Na pecuária extensiva, os animais (bois, bodes e cabras) ficam soltos em grandes áreas, comendo a vegetação. Bodes e cabras resistem bem à seca. 🐐"},
{n:"d",t:"Sub-regiões do Nordeste",q:"Qual comparação entre o Agreste e a Zona da Mata está correta?",a:["Agreste: pequenas propriedades; Zona da Mata: grandes canaviais","Agreste: grandes canaviais; Zona da Mata: pequenos sítios de leite","Agreste: Mata dos Cocais; Zona da Mata: Caatinga","Agreste: litoral; Zona da Mata: interior semiárido"],c:0,e:"No Agreste predominam pequenas e médias propriedades com policultura. Na Zona da Mata, desde a colonização, há grandes plantações de cana."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Por que muitas plantas da Caatinga têm espinhos e folhas pequenas?",a:["Para perder menos água no calor seco","Para enfeitar a paisagem no Natal","Para conseguir boiar nas enchentes","Para sobreviver ao frio e à neve do inverno sertanejo"],c:0,e:"Folhas pequenas e espinhos perdem menos água do que folhas grandes. É uma adaptação ao clima quente e seco. Os espinhos ainda protegem contra animais. 🌵"},
{n:"d",t:"Sub-regiões do Nordeste",q:"Cidades como Recife e Salvador concentram indústrias, comércio, portos e turismo. Isso se relaciona com qual característica da Zona da Mata?",a:["É a área mais povoada e urbanizada desde a colonização","É a sub-região mais seca e despovoada","Fica no interior semiárido, longe do mar e das rotas de navios","É coberta pela Mata dos Cocais"],c:0,e:"A Zona da Mata foi a primeira área ocupada pelos portugueses e até hoje concentra as maiores cidades, as indústrias e os portos do Nordeste."},
{n:"d",t:"Sub-regiões do Nordeste",q:"Qual alternativa relaciona corretamente uma sub-região do Nordeste a produtos típicos dela?",a:["Meio-Norte – babaçu e carnaúba","Zona da Mata – soja e trigo","Agreste – erva-mate e pinhão","Sertão – cacau à sombra da mata"],c:0,e:"Babaçu e carnaúba são da Mata dos Cocais, no Meio-Norte. O cacau é cultivado no sul da Bahia, na Zona da Mata, e erva-mate e pinhão são do Sul do Brasil."}
];
